package com.bulletin.app;
import org.junit.Test;
import java.time.*;
import static org.junit.Assert.*;

public class RewardAndMinimumTest {
    final ZoneId zone=ZoneId.of("UTC");
    final long now=Instant.parse("2026-11-11T12:00:00Z").toEpochMilli();
    Game.Quest quest(Game g,boolean repeat,boolean required){Game.Quest q=new Game.Quest();q.name="Task";q.firstDay=g.day;q.repeatable=repeat;q.required=required;q.forever=true;q.bountySince=now;g.addQuest(q);return q;}
    @Test public void historicalMustDoUndoKeepsItsOriginalReward()throws Exception {Game g=new Game(now,zone);Game.Quest q=quest(g,false,true);q.completedDay=g.day;q.completions=1;g.coins=10;g.history.add(new Game.HistoryEntry(Game.QUEST_HISTORY,q.id,q.name,now));org.json.JSONObject old=GameCodec.encodeLegacy(g).put("version",5);Game loaded=GameCodec.decode(old.toString(),now+1,zone);assertEquals(10,loaded.undo.get(0).reward);assertTrue(loaded.restoreOneOff(q.id,now+1));assertEquals(0,loaded.coins);}
    @Test public void missingUndoUsesKnownAwardEvenAfterMustDoFlagChanges(){Game g=new Game(now,zone);Game.Quest q=quest(g,false,true);g.completeInstant(q,now);assertEquals(30,g.coins);g.undo.clear();q.required=false;assertTrue(g.restoreOneOff(q.id,now+1));assertEquals(0,g.coins);}
    @Test public void maximumExtraWaitingBountyIsHalved(){assertEquals(40000,Game.agedBounty(10000,now,now+1000*3600000L));assertTrue(Game.agedBounty(10000,now,now+116*3600000L)<40000);assertEquals(40000,Game.agedBounty(10000,now,now+117*3600000L));}
    @Test public void mustDoExactlyDoublesOptionalRewardAfterRoundingAndWaiting(){for(boolean repeat:new boolean[]{false,true})for(int energy=Game.EXTRA;energy<=Game.RELAX;energy++)for(int hours:new int[]{0,1,120}){Game g=new Game(now,zone);g.energy=energy;g.nextBounty=133;Game.Quest q=quest(g,repeat,false);long at=now+hours*3600000L,optional=g.bountyFor(q,at);q.required=true;assertEquals(optional*2,g.bountyFor(q,at));assertTrue(g.start(q,now));assertEquals(optional*2,g.activeBounty(at));}}
    @Test public void categoryMustDoAndPausedQuestUseMatchingOptionalBaseline()throws Exception {Game g=new Game(now,zone);g.energy=Game.DEAD;g.nextBounty=133;Game.Quest q=quest(g,true,false);Game.Category c=new Game.Category();c.mustDo=true;c.requiredTasks=2;g.addCategory(c);g.assignCategory(q,c.id);assertEquals(22,g.bountyFor(q,now));g.start(q,now);g.pauseQuest(now+1000);g.energy=Game.EXTREME;g=GameCodec.decode(GameCodec.encode(g).toString(),now+2000,zone);q=g.quests.get(0);assertEquals(22,g.bountyFor(q,now+2000));g.start(q,now+2000);assertEquals(22,g.activeBounty(now+2000));}
    @Test public void requiredSinglePaysThirtyPercentAtEveryEnergyAndUndoRefundsIt(){for(int energy=Game.EXTRA;energy<=Game.RELAX;energy++){Game g=new Game(now,zone);g.energy=energy;g.nextBounty=101;Game.Quest q=quest(g,false,true);assertEquals(32,g.bountyFor(q));g.completeInstant(q,now);assertEquals(32,g.coins);assertTrue(g.restoreOneOff(q.id,now+1));assertEquals(0,g.coins);}}
    @Test public void minimumLawFineCreatesDebtAndEscalatesIndependentlyAfterRestart()throws Exception {Game g=new Game(now,zone);g.coins=100;Game.Fine a=new Game.Fine(),b=new Game.Fine();g.addLaw(a);g.addLaw(b);assertEquals(300,g.nextFine(a).coins(g.coins));g.incurFine(a,now);assertEquals(-200,g.coins);assertEquals(330,g.nextFine(a).coins(g.coins));assertEquals(300,g.nextFine(b).coins(g.coins));g=GameCodec.decode(GameCodec.encode(g).toString(),now+1,zone);g.incurFine(g.fines.get(0),now+1);assertEquals(-530,g.coins);assertEquals(363,g.nextFine(g.fines.get(0)).coins(g.coins));}
    @Test public void eachMissedSlotGetsMinimumAndDebtCanBeRefunded(){Game g=new Game(now,zone);quest(g,false,true);quest(g,false,true);assertEquals(630,g.requiredPenalty().coins(0));long midnight=LocalDate.ofEpochDay(g.day+1).atStartOfDay(zone).toInstant().toEpochMilli();g.advance(midnight,zone);assertEquals(-730,g.coins);assertEquals(630,g.missedReviews.get(0).coinsLost);g.resolveMissed(true,midnight+1,zone);assertEquals(-100,g.coins);}
    @Test public void penaltyRefundPreservesRentWhenTheFineCrossesItsDebtFloor(){Game g=new Game(now,zone);g.coins=-9950;quest(g,false,true);long midnight=LocalDate.ofEpochDay(g.day+1).atStartOfDay(zone).toInstant().toEpochMilli();g.advance(midnight,zone);assertEquals(-10250,g.coins);assertEquals(50,g.missedReviews.get(0).rentDifference);g.resolveMissed(true,midnight+1,zone);assertEquals(-10000,g.coins);}
    @Test public void monetaryBoundsStillPreventOverflow(){Game g=new Game(now,zone);quest(g,false,true);assertEquals(0,g.requiredPenalty().coins(-Game.LIMIT));assertEquals(1,g.requiredPenalty().coins(-Game.LIMIT+1));assertEquals(Game.LIMIT,Game.proportionalBounty(Game.LIMIT,true,2,1));}
}

